<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_login();
if(!has_permission('billing.overview')&&!has_permission('billing.view')&&!has_permission('invoices.manage')&&!has_permission('payments.manage')&&!has_permission('financial_reports.view')){http_response_code(403);exit('Billing access is not assigned to your account.');}
$canViewDetail=has_permission('billing.view')||has_permission('invoices.manage')||has_permission('payments.manage')||has_permission('financial_reports.view');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='invoice'){
  require_permission('invoices.manage');$patient=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT);$amount=trim((string)($_POST['total_amount']??''));$cents=preg_match('/^\d{1,10}(?:\.\d{1,2})?$/',$amount)?(int)round((float)$amount*100):0;
  if(!$patient||$cents<1){set_flash('danger','Select a patient and enter an invoice total greater than zero.');redirect('/hospital%20management/billing/index.php');}
  $number='INV-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$pdo->prepare("INSERT INTO invoices(patient_id,invoice_no,total_amount,status) VALUES(:patient,:number,:amount,'unpaid')");$q->execute(['patient'=>$patient,'number'=>$number,'amount'=>number_format($cents/100,2,'.','')]);$id=(string)$pdo->lastInsertId();record_audit('create','invoice',$id,'Invoice generated');set_flash('success','Invoice '.$number.' created.');
 }elseif($action==='payment'){
  require_permission('payments.manage');$invoice=filter_var($_POST['invoice_id']??'',FILTER_VALIDATE_INT);$amount=trim((string)($_POST['amount']??''));$cents=preg_match('/^\d{1,10}(?:\.\d{1,2})?$/',$amount)?(int)round((float)$amount*100):0;$method=(string)($_POST['method']??'');$reference=trim((string)($_POST['reference']??''));
  if(!$invoice||$cents<1||!in_array($method,['cash','mobile_money','card','insurance','bank_transfer','other'],true)||strlen($reference)>120){set_flash('danger','Enter a valid invoice, payment amount, method, and reference.');redirect('/hospital%20management/billing/index.php');}
  $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT total_amount,status FROM invoices WHERE id=:id FOR UPDATE');$q->execute(['id'=>$invoice]);$row=$q->fetch();if(!$row||$row['status']==='void')throw new RuntimeException('Invoice not found or void.');$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE invoice_id=:id');$q->execute(['id'=>$invoice]);$paidCents=(int)round((float)$q->fetchColumn()*100);$totalCents=(int)round((float)$row['total_amount']*100);if($cents>$totalCents-$paidCents)throw new RuntimeException('Payment exceeds the remaining invoice balance.');$q=$pdo->prepare('INSERT INTO payments(invoice_id,amount,method,reference,received_by) VALUES(:invoice,:amount,:method,:reference,:user)');$q->execute(['invoice'=>$invoice,'amount'=>number_format($cents/100,2,'.',''),'method'=>$method,'reference'=>$reference?:null,'user'=>current_user()['id']]);$newPaid=$paidCents+$cents;$status=$newPaid===$totalCents?'paid':'partial';$pdo->prepare('UPDATE invoices SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$invoice]);record_audit('payment','invoice',(string)$invoice,'Payment received');$pdo->commit();set_flash('success','Payment recorded and receipt issued.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Payment could not be recorded.');}
 }else{http_response_code(400);exit('Unknown billing action.');}redirect('/hospital%20management/billing/index.php');
}
$patients=has_permission('invoices.manage')?$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY last_name,first_name LIMIT 1000')->fetchAll():[];
$invoices=[];if($canViewDetail){$invoices=$pdo->query('SELECT i.id,i.invoice_no,i.total_amount,i.status,i.created_at,p.patient_no,p.first_name,p.last_name,COALESCE(SUM(pay.amount),0) AS paid FROM invoices i JOIN patients p ON p.id=i.patient_id LEFT JOIN payments pay ON pay.invoice_id=i.id GROUP BY i.id ORDER BY i.created_at DESC LIMIT 300')->fetchAll();}
$overview=null;if(has_permission('billing.overview')&&!$canViewDetail){$overview=['today'=>(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(paid_at)=CURDATE()')->fetchColumn(),'outstanding'=>(float)$pdo->query("SELECT COALESCE(SUM(i.total_amount-COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id=i.id),0)),0) FROM invoices i WHERE i.status IN ('unpaid','partial')")->fetchColumn()];}
$pageTitle='Billing and payments';require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><h2>Billing and payments</h2><p>Create patient invoices, receive payments, and print payment records.</p></div><button class="btn btn-outline-secondary" onclick="window.print()">Print</button></div>
<?php if($overview!==null):?><div class="row g-3"><div class="col-md-6"><article class="stat-card"><div class="stat-label">Today's collections</div><div class="stat-value"><?=number_format($overview['today'],2)?></div></article></div><div class="col-md-6"><article class="stat-card"><div class="stat-label">Outstanding balance</div><div class="stat-value"><?=number_format($overview['outstanding'],2)?></div></article></div></div><?php endif;?>
<?php if(has_permission('invoices.manage')):?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Generate invoice</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="invoice"><div class="col-md-6"><label class="form-label">Patient</label><select class="form-select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['patient_no'].' · '.$p['last_name'].', '.$p['first_name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Total amount</label><input class="form-control" name="total_amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Create invoice</button></div></form><div class="form-text mt-2">This starter records an invoice total; itemized service charges and insurance claim workflows are not included.</div></section><?php endif;?>
<?php if(has_permission('payments.manage')):?><section class="content-card form-card"><div class="card-heading"><h3>Receive payment</h3></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="payment"><div class="col-md-4"><label class="form-label">Invoice</label><select class="form-select" name="invoice_id" required><option value="">Select outstanding invoice</option><?php foreach($invoices as $i):if(!in_array($i['status'],['paid','void'],true)):$balance=max(0,(float)$i['total_amount']-(float)$i['paid']);?><option value="<?=(int)$i['id']?>"><?=e($i['invoice_no'].' · '.$i['patient_no'].' · Balance '.number_format($balance,2))?></option><?php endif;endforeach;?></select></div><div class="col-md-2"><label class="form-label">Amount</label><input class="form-control" type="number" name="amount" min="0.01" step="0.01" required></div><div class="col-md-2"><label class="form-label">Method</label><select class="form-select" name="method"><?php foreach(['cash','mobile_money','card','insurance','bank_transfer','other'] as $m):?><option value="<?=e($m)?>"><?=e(ucwords(str_replace('_',' ',$m)))?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Reference</label><input class="form-control" name="reference" maxlength="120"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Receive payment</button></div></form></section><?php endif;?>
<?php if($canViewDetail): ?><section class="content-card"><div class="card-heading"><h3>Invoices and receipts</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Patient</th><th>Date</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php if(!$invoices):?><tr><td class="empty-state" colspan="7">No invoices recorded.</td></tr><?php else:foreach($invoices as $i):$balance=max(0,(float)$i['total_amount']-(float)$i['paid']);?><tr><td><?=e($i['invoice_no'])?></td><td><?=e($i['last_name'].', '.$i['first_name'])?><br><span class="subtle"><?=e($i['patient_no'])?></span></td><td><?=e(date('M j, Y',strtotime($i['created_at'])))?></td><td><?=number_format((float)$i['total_amount'],2)?></td><td><?=number_format((float)$i['paid'],2)?></td><td><?=number_format($balance,2)?></td><td><?=e(ucfirst($i['status']))?></td></tr><?php if(has_permission('receipts.issue')&&$i['paid']>0):$q=$pdo->prepare('SELECT amount,method,reference,paid_at FROM payments WHERE invoice_id=:id ORDER BY paid_at DESC');$q->execute(['id'=>$i['id']]);foreach($q->fetchAll() as $receipt):?><tr class="subtle"><td colspan="2">Receipt</td><td><?=e(date('M j, Y g:i a',strtotime($receipt['paid_at'])))?></td><td><?=number_format((float)$receipt['amount'],2)?></td><td colspan="3"><?=e(ucwords(str_replace('_',' ',$receipt['method'])) . ($receipt['reference']?' · '.$receipt['reference']:''))?></td></tr><?php endforeach;endif;?><?php endforeach;endif;?></tbody></table></div></section><?php endif; ?>
<?php require __DIR__ . '/print-documents.php'; ?>
<?php require __DIR__.'/../includes/footer.php';?>
